contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _value) public {
        // ensure the test contract is the owner of c
        address owner = c.owner();

        // Precondition: we have enough Ether to be in a safe state, but we only
        // test the transfer behavior of withdraw. If the threshold balance is
        // insufficient, withdraw will revert. We want to test the two branches.
        // Since the test contract is the owner, we expect withdraw to succeed
        // only if the requested amount is not greater than c's balance.
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        bool reverted;
        try c.withdraw(_value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (_value <= cBalanceBefore) {
            // Owner can withdraw any amount up to the contract's balance
            assert(!reverted && address(this).balance == thisBalanceBefore + _value);
        } else {
            // Owner cannot withdraw more than the contract's balance
            assert(reverted);
        }
    }

    receive() external payable {}
}

